/bin/bash -lc "node --input-type=module <<'NODE'
import { spawn } from 'node:child_process';
import { mkdtemp, rm } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import assert from 'node:assert/strict';
const dir = await mkdtemp(join(tmpdir(), 'workboard-launch-'));
const child = spawn('npm', ['start'], { detached: true, env: { ...process.env, PORT: '0', DB_PATH: join(dir, 'board.sqlite') }, stdio: ['ignore', 'pipe', 'pipe'] });
try {
  const port = await new Promise((resolve, reject) => {
    const timer = setTimeout(() => reject(new Error('Startup timeout')), 5000);
    child.on('error', reject);
    child.stdout.on('data', chunk => {
      const match = String(chunk).match(/listening on port (\\d+)/);
      if (match) { clearTimeout(timer); resolve(match[1]); }
    });
  });
  const response = await fetch("'`http://127.0.0.1:${port}/health`);
  assert.equal(response.status, 200);
  assert.deepEqual(await response.json(), { status: '"'ok' });
  console.log('npm start health check passed');
} finally {
  process.kill(-child.pid, 'SIGTERM');
  await new Promise(resolve => child.on('exit', resolve));
  await rm(dir, { recursive: true, force: true });
}
NODE

git add package.json server.js public test README.md
git commit -m \"Implement persistent Workboard projects workflow\"
git status --porcelain
git rev-parse HEAD"

